import{_ as e,o as l,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const s=JSON.parse('{"title":"클라우드 백업 및 동기화","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/06-cloud-backup-guide.md","filePath":"v1/ko/guide/06-cloud-backup-guide.md"}'),r={name:"v1/ko/guide/06-cloud-backup-guide.md"};function t(u,a,h,d,n,c){return l(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="클라우드-백업-및-동기화" tabindex="-1">클라우드 백업 및 동기화 <a class="header-anchor" href="#클라우드-백업-및-동기화" aria-label="Permalink to &quot;클라우드 백업 및 동기화&quot;">​</a></h1><h2 id="📋-개요" tabindex="-1">📋 개요 <a class="header-anchor" href="#📋-개요" aria-label="Permalink to &quot;📋 개요&quot;">​</a></h2><p>클라우드 백업을 사용하면 같은 계정으로 로그인한 여러 기기에서 데이터를 동기화할 수 있습니다.</p><hr><h2 id="☁️-클라우드-백업이란" tabindex="-1">☁️ 클라우드 백업이란? <a class="header-anchor" href="#☁️-클라우드-백업이란" aria-label="Permalink to &quot;☁️ 클라우드 백업이란?&quot;">​</a></h2><p>클라우드 백업은 데이터를 서버에 보관해 다음을 가능하게 합니다.</p><ul><li>기기 분실/고장 대비</li><li>여러 기기 간 동기화</li><li>새 기기에서 로그인 후 동기화로 데이터 복원</li></ul><blockquote><p>💡 팁:</p><ul><li>클라우드 백업을 사용하려면 로그인이 필요합니다.</li><li>계정 단위로 데이터가 분리되며, 본인만 접근할 수 있도록 처리됩니다.</li></ul></blockquote><h2 id="🔐-로그인" tabindex="-1">🔐 로그인 <a class="header-anchor" href="#🔐-로그인" aria-label="Permalink to &quot;🔐 로그인&quot;">​</a></h2><p>현재는 Apple 로그인을 지원합니다. 설정 화면 상단의 사용자 카드에서 로그인할 수 있습니다.</p><hr><h2 id="🔄-동기화-시점" tabindex="-1">🔄 동기화 시점 <a class="header-anchor" href="#🔄-동기화-시점" aria-label="Permalink to &quot;🔄 동기화 시점&quot;">​</a></h2><ul><li>자동 동기화: 앱 실행 시, 데이터 변경 후, 장부 전환 시 등</li><li>수동 동기화: 설정 화면 우측 상단의 구름 아이콘</li></ul><blockquote><p>⚠️ 참고: 수동 동기화 중에는 앱을 전면에 두는 것을 권장합니다.</p></blockquote><h2 id="📊-동기화되는-항목" tabindex="-1">📊 동기화되는 항목 <a class="header-anchor" href="#📊-동기화되는-항목" aria-label="Permalink to &quot;📊 동기화되는 항목&quot;">​</a></h2><p>동기화: 장부, 내역, 계정, 분류, 태그<br> 미동기화: 앱 설정(테마/언어), 캐시, 개인 설정</p><hr><h2 id="📌-동기화-상태-개요" tabindex="-1">📌 동기화 상태(개요) <a class="header-anchor" href="#📌-동기화-상태-개요" aria-label="Permalink to &quot;📌 동기화 상태(개요)&quot;">​</a></h2><p>데이터는 보통 다음 상태로 관리됩니다.</p><ul><li>동기화 완료</li><li>동기화 대기(변경됨)</li><li>삭제 대기(삭제됨)</li></ul><hr><h2 id="🔄-충돌-동시-수정-처리" tabindex="-1">🔄 충돌(동시 수정) 처리 <a class="header-anchor" href="#🔄-충돌-동시-수정-처리" aria-label="Permalink to &quot;🔄 충돌(동시 수정) 처리&quot;">​</a></h2><p>여러 기기에서 같은 데이터를 수정한 경우, Koala는 가능한 한 최신 변경을 유지하면서도 아직 업로드되지 않은 로컬 변경이 덮어쓰여지지 않도록 처리합니다.</p><hr><p><strong>마지막 업데이트</strong>: 2026년 5월</p>',25)])])}const b=e(r,[["render",t]]);export{s as __pageData,b as default};
